<?php $pageTitle='Movimientos'; ?>
<section class="page-head"><div><p class="eyebrow">Historial</p><h1>Todos tus movimientos</h1><p class="muted">Aquí puedes consultar, editar o eliminar tus registros.</p></div><a class="btn" href="index.php?url=dashboard">← Volver al inicio</a></section>
<div class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Tipo</th><th>Categoría</th><th>Método</th><th>Descripción</th><th>Monto</th><th>Acciones</th></tr></thead><tbody><?php foreach($transactions as $t): ?><tr><td><?=date('d/m/Y',strtotime($t['date']))?></td><td><span class="badge <?=$t['type']?>"><?=$t['type']==='income'?'Ingreso':'Gasto'?></span></td><td><?=htmlspecialchars($t['category'])?></td><td><?=htmlspecialchars($t['payment_method'])?></td><td><?=htmlspecialchars($t['description']??'—')?></td><td class="money <?=$t['type']?>"><?=$t['type']==='income'?'+':'-'?>$<?=number_format($t['amount'],0,',','.')?></td><td class="actions"><a class="btn tiny" href="index.php?url=transaction/edit&id=<?=$t['id']?>">Editar</a><form method="post" action="index.php?url=transaction/delete" onsubmit="return confirm('¿Eliminar este movimiento?')"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['csrf']??'')?>"><input type="hidden" name="id" value="<?=$t['id']?>"><button class="btn tiny danger">Eliminar</button></form></td></tr><?php endforeach; if(!$transactions): ?><tr><td colspan="7" class="empty">No hay movimientos.</td></tr><?php endif; ?></tbody></table></div><div class="pagination"><?php if($page>1): ?><a class="btn tiny" href="index.php?url=transactions&page=<?=$page-1?>">Anterior</a><?php endif; ?><?php if($hasMore): ?><a class="btn tiny primary" href="index.php?url=transactions&page=<?=$page+1?>">Ver más</a><?php endif; ?></div></div>
